mapper.select:
SELECT DATE_FORMAT(access_time, '%H:00') AS time, COUNT(*) AS count FROM access_record WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY DATE_FORMAT(access_time, '%H:00') ORDER BY time

SELECT DATE_FORMAT(access_time, '%Y-%m-%d') AS date, COUNT(*) AS count FROM access_record WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY DATE_FORMAT(access_time, '%Y-%m-%d') ORDER BY date

SELECT access_area AS area, COUNT(*) AS count FROM access_record WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY access_area ORDER BY count DESC

SELECT user_name AS userName, COUNT(*) AS count FROM access_record WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY user_name ORDER BY count DESC
